<?php  use App\Models\User; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\Password;  test('reset password screen can be rendered', function () {     $response = $this->get('/reset-password/sample-token');      $response->assertStatus(200); });  test('password can be reset with valid token', function () {     $user = User::factory()->create();      $token = Password::createToken($user);      $response = $this->post('/reset-password', [         'token' => $token,         'email' => $user->email,         'password' => 'password123',         'password_confirmation' => 'password123',     ]);      $response->assertSessionHasNoErrors();     $response->assertRedirect(route('login'));      $this->assertTrue(Hash::check('password123', $user->fresh()->password)); });  test('password cannot be reset with invalid token', function () {     $user = User::factory()->create();      $response = $this->post('/reset-password', [         'token' => 'invalid-token',         'email' => $user->email,         'password' => 'password123',         'password_confirmation' => 'password123',     ]);      $response->assertSessionHasErrors('email'); });